import{_ as e,r as a,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"页面 - October CMS - 3.x","titleTemplate":false,"description":"为网站上的每个页面定义 URL。","frontmatter":{"subtitle":"为网站上的每个页面定义 URL。"},"headers":[{"level":2,"title":"页面配置","slug":"页面配置","link":"#页面配置","children":[{"level":3,"title":"URL 语法","slug":"url-语法","link":"#url-语法","children":[]}]},{"level":2,"title":"动态页面","slug":"动态页面","link":"#动态页面","children":[{"level":3,"title":"页面执行生命周期","slug":"页面执行生命周期","link":"#页面执行生命周期","children":[]},{"level":3,"title":"发送自定义响应","slug":"发送自定义响应","link":"#发送自定义响应","children":[]},{"level":3,"title":"处理表单","slug":"处理表单","link":"#处理表单","children":[]}]},{"level":2,"title":"404 页面","slug":"_404-页面","link":"#_404-页面","children":[]},{"level":2,"title":"错误页面","slug":"错误页面","link":"#错误页面","children":[]},{"level":2,"title":"设置页面标题","slug":"设置页面标题","link":"#设置页面标题","children":[{"level":3,"title":"使用页面属性","slug":"使用页面属性","link":"#使用页面属性","children":[]},{"level":3,"title":"使用占位符变量","slug":"使用占位符变量","link":"#使用占位符变量","children":[]}]},{"level":2,"title":"以编程方式注入页面资产","slug":"以编程方式注入页面资产","link":"#以编程方式注入页面资产","children":[]}],"relativePath":"3.x/zh-cn/cms/themes/pages.md","filePath":"3.x/zh-cn/cms/themes/pages.md"}'),u={name:"3.x/zh-cn/cms/themes/pages.md"};function r(k,n,d,g,h,v){const t=a("pre-heading"),p=a("post-heading");return o(),c("div",null,[s(t),n[0]||(n[0]=l("h1",null,"页面",-1)),s(p),n[1]||(n[1]=i(`<p>每个网站至少提供一个页面，在 October CMS 中，页面由页面模板表示。页面模板文件位于主题中的 <strong>pages</strong> 目录中。页面文件名不影响路由，但最好根据页面的功能来命名您的页面。文件应具有 <strong>htm</strong> 扩展名。</p><p>配置部分和 Twig 模板部分对于页面是必需的，但 PHP 代码部分是可选的。下面，您可以看到最简单的首页示例。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello, world!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><h2 id="页面配置"><a href="#页面配置" class="header-anchor">#</a> 页面配置</h2><p>页面配置在页面模板文件的配置部分中定义。页面配置定义了页面参数，这些参数是路由和渲染页面及其<a href="./components.html">组件</a>所必需的，组件将在另一篇文章中解释。页面支持以下配置参数：</p><div class="table"><table tabindex="0"><thead><tr><th>参数</th><th>描述</th></tr></thead><tbody><tr><td><strong>url</strong></td><td>页面 URL，必填。URL 语法在下面描述。</td></tr><tr><td><strong>title</strong></td><td>页面标题，必填。</td></tr><tr><td><strong>layout</strong></td><td>页面<a href="./layouts.html">布局</a>，可选。如果指定，应包含布局文件的名称（不带扩展名），例如：<code>default</code>。</td></tr><tr><td><strong>description</strong></td><td>后端界面的页面描述，可选。</td></tr><tr><td><strong>hidden</strong></td><td>隐藏的页面只能由已登录的后端用户访问，可选。</td></tr></tbody></table></div><h3 id="url-语法"><a href="#url-语法" class="header-anchor">#</a> URL 语法</h3><p>页面 URL 使用 <strong>url</strong> 配置参数定义。URL 应以正斜杠字符开头，并且可以包含参数。没有参数的 URL 是固定和严格的。在以下示例中，页面 URL 为 <code>/blog</code>。</p><div class="custom-block tip"><p>页面 URL 默认不区分大小写。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
</code></pre></div></div><p>带参数的 URL 更加灵活。在以下示例中定义的 URL 模式的页面将为任何类似 <code>/blog/post/something</code> 的地址显示。URL 参数可以由 October 组件或从页面 PHP 代码部分访问。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/post/:post_id</span>&quot;</span>
</code></pre></div><p>以下是从页面的 PHP 代码部分访问 URL 参数的方法（有关更多详细信息，请参阅动态页面部分）。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/post/:post_id</span>&quot;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$postId</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">param</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post_id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code></code></pre></div></div><p>参数名称应与 PHP 变量名兼容。要使参数成为可选的，请在其名称后添加问号：</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/post/:post_id?</span>&quot;</span>
</code></pre></div><p>URL 中间的参数不能是可选的。在下一个示例中，<code>:post_id</code> 参数被标记为可选，但会被处理为必需的。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/:post_id?/comments</span>&quot;</span>
</code></pre></div><p>可选参数可以有默认值，当 URL 中未提供实际参数值时，这些默认值用作后备值。默认值不能包含任何星号、管道符号或问号。默认值在<strong>问号</strong>后指定。在下一个示例中，对于 URL <code>/blog/category</code>，<code>category_id</code> 参数将为 <code>10</code>。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/category/:category_id?10</span>&quot;</span>
</code></pre></div><p>您还可以使用正则表达式来验证参数。要添加验证表达式，请在参数名称或问号后添加管道符号，并指定表达式。这些表达式中不允许使用正斜杠符号。示例：</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;/blog/:post_id|^[0-9]+$/comments&quot; ; this will match /blog/10/comments</span>

<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;/blog/:post_id|^[0-9]+$&quot; ; this will match /blog/3</span>

<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;/blog/:post_name?|^[a-z0-9\\-]+$&quot; ; this will match /blog/my-blog-post</span>
</code></pre></div><p>可以通过在参数后放置<strong>星号</strong>来使用特殊的<em>通配符</em>参数。与常规参数不同，通配符参数可以匹配一个或多个 URL 段。URL 只能包含一个通配符参数，不能使用正则表达式，也不能后跟可选参数。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/:category*/:slug</span>&quot;</span>
</code></pre></div><p>通配符参数本身也可以通过在星号前加上 <code>?</code> 字符来设为可选。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/:slug?*</span>&quot;</span>
</code></pre></div><p>例如，像 <code>/color/:color/make/:make*/edit</code> 这样的 URL 将匹配 <code>/color/brown/make/volkswagen/beetle/retro/edit</code> 并提取以下参数值：</p><ul><li>color: <code>brown</code></li><li>make: <code>volkswagen/beetle/retro</code></li></ul><div class="custom-block tip"><p>子目录不影响页面 URL - URL 仅由 <strong>url</strong> 参数定义。</p></div><h2 id="动态页面"><a href="#动态页面" class="header-anchor">#</a> 动态页面</h2><p>在页面模板的 Twig 部分中，您可以使用任何 <a href="./../../markup/templating.html">October CMS 提供的函数、过滤器和标签</a>。任何动态页面都需要<strong>变量</strong>，变量可以由页面或布局的 PHP 代码部分准备，或由<a href="./components.html">组件</a>准备。在本文中，我们描述如何在 PHP 代码部分中准备变量。</p><h3 id="页面执行生命周期"><a href="#页面执行生命周期" class="header-anchor">#</a> 页面执行生命周期</h3><p>在页面和布局的 PHP 代码部分中可以定义特殊函数：<code>onInit</code>、<code>onStart</code> 和 <code>onEnd</code>。<code>onInit</code> 函数在所有组件初始化后和处理 AJAX 请求之前执行。<code>onStart</code> 函数在页面执行开始时执行。<code>onEnd</code> 函数在页面渲染之前和页面<a href="./components.html">组件</a>执行之后执行。在 <code>onStart</code> 和 <code>onEnd</code> 函数中，您可以向 Twig 环境注入变量。使用带数组表示法的 <code>$this</code> 将变量传递给页面。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/</span>&quot;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;hello&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string double-quoted-string">&quot;Hello world!&quot;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> hello <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>下一个示例更为复杂。它展示了如何从数据库加载博客文章集合并在页面上显示（<code>Acme\\Blog</code> 插件是虚构的）。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Post</span><span class="token punctuation">;</span>

<span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;created_at&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;desc&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span>Latest posts<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>content <span class="token delimiter punctuation">}}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>October CMS 提供的默认变量和 Twig 扩展在<a href="./../../markup/templating.html">标记指南</a>中进行了描述。处理程序的执行顺序在<a href="./layouts.html">动态布局部分</a>中进行了描述。</p><h3 id="发送自定义响应"><a href="#发送自定义响应" class="header-anchor">#</a> 发送自定义响应</h3><p>在执行生命周期中定义的所有方法都有能力中止进程并返回响应 - 只需从生命周期函数中返回响应即可。下面的示例不会加载任何页面内容，而是将字符串 <em>Hello world!</em> 返回给浏览器：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>一个更有用的例子可能是使用 <code>Redirect</code> facade 触发重定向：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;http://google.com&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="处理表单"><a href="#处理表单" class="header-anchor">#</a> 处理表单</h3><p>您可以使用在页面或布局 PHP 代码部分中定义的处理程序方法来处理标准表单（AJAX 请求的处理在 <a href="./../ajax/introduction.html">AJAX 框架</a>文章中进行了解释）。使用 <code>form_open()</code> <a href="./../../markup/function/form.html">Twig 函数</a>来定义引用事件处理程序的表单。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onHandleForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span><span class="token punctuation">&gt;</span></span>Please enter a string<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>value<span class="token punctuation">&quot;</span></span><span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Submit
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Last submitted value: {{ lastValue }}<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p><code>onHandleForm</code> 函数可以在页面或布局的 PHP 代码部分中定义。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onHandleForm</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;lastValue&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>处理程序使用 <code>post</code> 函数加载值，并初始化页面的 <code>lastValue</code> 属性变量，该变量在第一个示例中显示在表单下方。</p><div class="custom-block tip"><p>如果在页面布局、页面和<a href="./components.html">页面组件</a>中定义了同名的处理程序，October CMS 将执行页面处理程序。如果在组件和布局中定义了处理程序，则将执行布局处理程序。处理程序优先级为：页面、布局、组件。</p></div><p>如果您想引用特定组件中定义的处理程序，请在处理程序引用中使用组件的名称或别名：</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myComponent::onHandleForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>...<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="_404-页面"><a href="#_404-页面" class="header-anchor">#</a> 404 页面</h2><p>如果主题包含 URL 为 <code>/404</code> 的页面，则当系统找不到请求的页面时将显示该页面。</p><h2 id="错误页面"><a href="#错误页面" class="header-anchor">#</a> 错误页面</h2><p>默认情况下，任何错误都会显示一个详细的错误页面，其中包含文件内容、行号和发生错误的堆栈跟踪。您可以通过在 <code>config/app.php</code> 脚本中将配置值 <code>debug</code> 设置为 <strong>false</strong>，并创建 URL 为 <code>/error</code> 的页面来显示自定义错误页面。</p><h2 id="设置页面标题"><a href="#设置页面标题" class="header-anchor">#</a> 设置页面标题</h2><p>可以在 PHP 中使用 Page 对象，或在 Twig 中使用<a href="./../../markup/tag/placeholder.html">占位符标签</a>来设置页面标题。</p><h3 id="使用页面属性"><a href="#使用页面属性" class="header-anchor">#</a> 使用页面属性</h3><p>页面的属性可以在 PHP 代码部分或<a href="./components.html">组件</a>中通过引用 <code>$this-&gt;page</code> 来访问。以下示例将 <code>meta_title</code> 属性设置为新值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onEnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token operator">-&gt;</span><span class="token property">meta_title</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;A different page title&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>可以在 Twig 中使用 <code>this.page</code> 变量访问 <code>{{ this.page }}</code> 变量。例如，在布局中返回 <code>meta_title</code> 属性。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> this<span class="token punctuation">.</span>page<span class="token punctuation">.</span>meta_title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>有关 <code>this.page</code> 的更多信息可以在<a href="./../../markup/property/this-page.html">标记指南</a>中找到。</p></div><h3 id="使用占位符变量"><a href="#使用占位符变量" class="header-anchor">#</a> 使用占位符变量</h3><p><code>{% put %}</code> 标签允许您将值存储在占位符变量中。以下示例设置了 <code>pageTitle</code> 变量。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> pageTitle <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&#39;</span>Yet another page title<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p><code>placeholder()</code> Twig 函数用于在布局中访问该变量。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> placeholder<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>pageTitle<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>可以提供默认值（第二个参数）作为后备。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> placeholder<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>pageTitle<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> this<span class="token punctuation">.</span>page<span class="token punctuation">.</span>meta_title<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>有关占位符标签的更多信息可以在<a href="./../../markup/tag/placeholder.html">占位符标签文章</a>中找到。</p></div><h2 id="以编程方式注入页面资产"><a href="#以编程方式注入页面资产" class="header-anchor">#</a> 以编程方式注入页面资产</h2><p>如果需要，您可以使用控制器的 <code>addCss</code> 和 <code>addJs</code> 方法将资产（CSS 和 JavaScript 文件）注入页面。这可以在页面或<a href="./layouts.html">布局模板</a>的 PHP 代码部分中定义的 <code>onStart</code> 函数中完成。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addCss</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;assets/css/hello.css&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;assets/js/app.js&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>如果 <code>addCss</code> 和 <code>addJs</code> 方法参数中指定的路径以斜杠 (/) 开头，则它将相对于网站根目录。如果资产路径不以斜杠开头，则它相对于主题。</p><p>注入的资产可以通过将它们作为数组传递来合并：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addCss</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;assets/css/hello.css&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;assets/css/goodbye.css&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;assets/js/app.js&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;assets/js/nav.js&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>LESS 和 SCSS 资产可以使用合并器注入和编译。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addCss</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;assets/less/base.less&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><code>addCss</code> 和 <code>addJs</code> 的第二个参数允许您为注入的资产提供额外的属性：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;assets/js/app.js&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;assets/js/nav.js&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;defer&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>要在页面或<a href="./layouts.html">布局</a>上输出注入的资产，请使用 <code>{% styles %}</code> 和 <code>{% scripts %}</code> 标签。示例：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
    ...
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">styles</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    ...
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">scripts</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>有关 <code>{% styles %}</code> 和 <code>{% scripts %}</code> 标签的更多信息可以在<a href="./../../markup/tag/placeholder.html">标记指南</a>中找到。</p></div>`,83))])}const w=e(u,[["render",r]]);export{f as __pageData,w as default};
